target.description:
Polymorphic target. Shapes:
  { type: 'row',           rowId: '<cuid>' }
  { type: 'cell',          rowId: '<cuid>', columnKey: '<key>' }
  { type: 'doc_range',     surfaceSlug: '<slug>', anchor: { from: <number>, to: <number>, text: '<plain>' } }
  { type: 'html_element',  surfaceSlug: '<slug>', anchor: { selector: '<css>', text?: '<plain>' } }
  { type: 'surface',       surfaceSlug: '<slug>' }
  { type: 'workspace' }
